    internal static class SettlementRoadSurfaceValidation {
        [Serializable]sealed class Row {public string name;public double medianMs,p95Ms,updatesPerSecond;public long managedHeapGrowthBytes,unityAllocated,unityReserved,workingSet;}
        [Serializable]sealed class Report {public string scope="Isolated standalone CPU infrastructure/identity operations; timings are operation time, not full-world frame time. No army/fog acceptance claim.";public List<Row> rows=new List<Row>();public int roadCount;public long oldRoadGeometryBytes,sparseRoadGpuBytes;}
        [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]struct Memory {public uint size,faults;public UIntPtr peakWorkingSet,workingSet,peakPaged,paged,peakNonPaged,nonPaged,pagefile,peakPagefile,privateBytes;}
        [System.Runtime.InteropServices.DllImport("kernel32.dll")]static extern IntPtr GetCurrentProcess();[System.Runtime.InteropServices.DllImport("psapi.dll")]static extern bool GetProcessMemoryInfo(IntPtr process,out Memory counters,uint size);
