        static void Set(object instance,string name,object value)=>instance.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).SetValue(instance,value);
        static long Key(PlanetNavCoordinate c)=>((long)(int)c.face<<48)|((long)c.x<<24)|(uint)c.y;
        internal static void Run(Action<bool,string> check){
            var report=new Report();check(Allocation(()=>GC.KeepAlive(new byte[1048576]))>=1048576,"Managed heap allocation measurement detects a known 1 MiB control allocation");var go=new GameObject("Inactive road metadata fixture");go.SetActive(false);var world=go.AddComponent<PlanetDevelopment>();var planet=ScriptableObject.CreateInstance<PlanetDefinition>();planet.radius=120000000;world.definition=planet;
            var local=(PlanetRtsBase)FormatterServices.GetUninitializedObject(typeof(PlanetRtsBase));Set(local,"fixture",world);var buildings=new List<RtsBuilding>();Set(local,"Buildings",buildings);
            var grid=new PlanetConstructionGrid(1,planet.radius,32);typeof(PlanetRtsBase).GetProperty("Grid").SetValue(local,grid);
            var areas=typeof(PlanetRtsBase).GetField("buildingAreas",BindingFlags.Instance|BindingFlags.NonPublic);areas.SetValue(local,Activator.CreateInstance(areas.FieldType));
            var saved=new List<RoadTile>(50000);int origin=grid.Resolution/2;for(int y=0;y<200;y++)for(int x=0;x<200;x++)saved.Add(new RoadTile{cell=new PlanetNavCoordinate(1,CubeFace.PositiveY,origin+x,origin+y),faction=0});
            var network=new SettlementRoadNetwork(world,local,saved,32);local.Roads=network;var append=(Action<int>)Delegate.CreateDelegate(typeof(Action<int>),network,typeof(SettlementRoadNetwork).GetMethod("AppendGraph",BindingFlags.Instance|BindingFlags.NonPublic));
            var owners=(Dictionary<long,int>)typeof(SettlementRoadNetwork).GetField("tiles",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(network);
            var before=network.Nodes;int resets=0;network.GraphReset+=()=>resets++;
            for(int i=0;i<20;i++)network.RefreshBuildings();check(ReferenceEquals(before,network.Nodes)&&resets==0,"Ordinary building refreshes retain the graph buffer and never rebuild road topology");
            int first=saved.Count;saved.Add(new RoadTile{cell=new PlanetNavCoordinate(1,CubeFace.PositiveY,origin+200,origin),faction=0});owners[Key(saved[first].cell)]=0;append(first);
            check(network.Nodes[first].west==199&&network.Nodes[199].east==first&&network.Component(first)==network.Component(0),"An appended road joins its existing component and updates reciprocal links");
            first=saved.Count;saved.Add(new RoadTile{cell=new PlanetNavCoordinate(1,CubeFace.PositiveY,origin+201,origin),faction=1});owners[Key(saved[first].cell)]=1;append(first);check(network.Nodes[first].west<0&&network.Component(first)!=network.Component(0),"Incremental connectivity does not join enemy-owned road cells");
            var gateDefinition=new BuildingDefinition{id="gate",footprintWidth=1,footprintDepth=1,time=1};var gate=new RtsBuilding{definition=gateDefinition,construction=1,position=CubeSphere.Encode(grid.Direction(saved[0].cell)),team=0,gateOpen=false};buildings.Add(gate);network.RefreshBuildings();var area=local.Area(gate);int gateNode=network.Node(grid.Direction(new PlanetNavCoordinate(1,area.face,area.x,area.y)));check(gateNode>=0&&network.Nodes[gateNode].west<0&&network.Nodes[gateNode].east<0&&network.Nodes[gateNode].south<0&&network.Nodes[gateNode].north<0,"Closing a gate still disconnects its GPU road node");gate.gateOpen=true;network.RefreshBuildings();check(network.Nodes[gateNode].east>=0||network.Nodes[gateNode].west>=0,"Opening a gate restores graph connectivity");buildings.Clear();network.RefreshBuildings();
            var house=new RtsBuilding{definition=new BuildingDefinition{id="fixture_house",footprintWidth=1,footprintDepth=1,time=1},construction=1,position=CubeSphere.Encode(grid.Direction(new PlanetNavCoordinate(1,CubeFace.PositiveY,origin+500,origin+500))),team=0};
            var housePort=grid.Port(local.Area(house));first=saved.Count;saved.Add(new RoadTile{cell=housePort});owners[Key(housePort)]=0;append(first);buildings.Add(house);int previousResets=resets;network.RefreshBuildings();check(saved[first].connections!=0&&resets==previousResets&&network.Nodes[first].west<0&&network.Nodes[first].east<0&&network.Nodes[first].south<0&&network.Nodes[first].north<0,"A building adds its painted entrance arm without a graph rebuild or a traversable node inside the building");buildings.Clear();network.RefreshBuildings();check(saved[first].connections==0&&resets==previousResets,"Removing a building clears its painted entrance arm without rebuilding the network");
            for(int face=0;face<6;face++)for(int edge=0;edge<4;edge++){var cell=new PlanetNavCoordinate(1,(CubeFace)face,edge==0?0:edge==1?grid.Resolution-1:origin,edge==2?0:edge==3?grid.Resolution-1:origin);var adjacent=CubeSphere.Neighbour(cell,edge==0?-1:edge==1?1:0,edge==2?-1:edge==3?1:0,grid.Resolution);var seam=new SettlementRoadNetwork(world,local,new List<RoadTile>{new RoadTile{cell=cell},new RoadTile{cell=adjacent}},32);check(seam.Component(0)==seam.Component(1),"Road component crosses cube face "+face+" edge "+edge);}
            var frontier=new SettlementRoadNetwork.Frontier();for(int i=8191;i>=0;i--)frontier.Add((i%17,i));double previousScore=-1;long previousKey=-1;bool ordered=true;while(frontier.Count>0){var next=frontier.Pop();ordered&=next.score>previousScore||next.score==previousScore&&next.key>previousKey;previousScore=next.score;previousKey=next.key;}check(ordered,"Retained road-search heap preserves score ordering and deterministic key ties");
            void ReuseFrontier(){frontier.Clear();for(int i=8191;i>=0;i--)frontier.Add((i%17,i));while(frontier.Count>0)frontier.Pop();}ReuseFrontier();check(Allocation(ReuseFrontier)==0,"Warm road search frontier reuses storage with no measured managed heap growth");
            var tree=new SortedSet<(double score,long key)>();void PriorFrontier(){tree.Clear();for(int i=8191;i>=0;i--)tree.Add((i%17,i));while(tree.Count>0)tree.Remove(tree.Min);}
            Measure(report,"Previous 8192-node road search frontier",PriorFrontier,30);Measure(report,"Retained 8192-node road search frontier",ReuseFrontier,30);
            var cells=new SettlementRoadSurface.Cell[131072];for(uint i=0;i<41726;i++){uint face=i%6+1,x=(i*7919u)%(uint)grid.Resolution,y=(i*65537u)%(uint)grid.Resolution;int slot=SettlementRoadSurface.Slot(cells,face,x,y);cells[slot]=new SettlementRoadSurface.Cell{face=face,x=x,y=y,mask=i%16};}
            bool accurate=true;for(uint i=0;i<41726;i++){uint face=i%6+1,x=(i*7919u)%(uint)grid.Resolution,y=(i*65537u)%(uint)grid.Resolution;int slot=SettlementRoadSurface.Slot(cells,face,x,y);accurate&=cells[slot].mask==i%16;}check(accurate,"Sparse paint resolves 41,726 cells across all six faces at 1000x scale");
            // Compare the former complete graph algorithm with bounded append work.
            var legacyIndices=new Dictionary<long,int>();var pending=new Queue<int>();
            void Legacy(){legacyIndices.Clear();for(int i=0;i<saved.Count;i++)legacyIndices[Key(saved[i].cell)]=i;var nodes=new SettlementRoadNetwork.GpuNode[saved.Count];var labels=new int[saved.Count];Array.Fill(labels,-1);
                for(int i=0;i<saved.Count;i++){var tile=saved[i];var node=new SettlementRoadNetwork.GpuNode{west=-1,east=-1,south=-1,north=-1};for(int e=0;e<4;e++){var c=CubeSphere.Neighbour(tile.cell,e==0?-1:e==1?1:0,e==2?-1:e==3?1:0,grid.Resolution);if(!legacyIndices.TryGetValue(Key(c),out int other)||saved[other].faction!=tile.faction)continue;switch(e){case 0:node.west=other;break;case 1:node.east=other;break;case 2:node.south=other;break;default:node.north=other;break;}}Vector3 p=grid.Direction(tile.cell)*(planet.radius+tile.height+1);node.position=new Vector4(p.x,p.y,p.z,tile.faction);nodes[i]=node;}
                for(int i=0;i<nodes.Length;i++){if(labels[i]>=0)continue;labels[i]=i;pending.Enqueue(i);while(pending.Count>0){var n=nodes[pending.Dequeue()];Visit(n.west,i);Visit(n.east,i);Visit(n.south,i);Visit(n.north,i);}}void Visit(int i,int root){if(i<0||labels[i]>=0)return;labels[i]=root;pending.Enqueue(i);} }
            Measure(report,"Previous full graph reconstruction, ~40k roads",Legacy,30);
            int nextX=202;
            void Incremental(){int start=saved.Count;var cell=new PlanetNavCoordinate(1,CubeFace.PositiveY,origin+nextX++,origin);saved.Add(new RoadTile{cell=cell});owners[Key(cell)]=0;append(start);}
            Incremental();Measure(report,"Incremental graph append, ~40k roads",Incremental,30);
            var colony=new ColonyState();for(int i=1;i<=1600;i++)colony.residents.Add(new ResidentState{id=i});for(int i=1;i<=400;i++)colony.households.Add(new HouseholdState{id=i});CivilisationRuntime.Person(colony,100);CivilisationRuntime.Family(colony,1);
            int cursor=1;void PriorLookup(){for(int j=0;j<1000;j++){long id=1+(cursor++%1600);if(colony.residents.Find(p=>p.id==id)==null)throw new Exception("Missing resident");}}
            void Lookup(){for(int j=0;j<1000;j++){long id=1+(cursor++%1600);if(CivilisationRuntime.Person(colony,id)==null)throw new Exception("Missing indexed resident");}}
            Measure(report,"Previous 1000 resident lookups",PriorLookup,30);Measure(report,"Indexed 1000 resident lookups",Lookup,30);
            long lookupBytes=Allocation(Lookup);check(lookupBytes==0,"Warm resident identity lookup has no measured managed heap growth");
            colony.residents.RemoveAt(99);check(CivilisationRuntime.Person(colony,100)==null&&CivilisationRuntime.Person(colony,101)?.id==101,"Identity index updates after archived resident removal");colony.residents[5]=new ResidentState{id=9000};colony.societyRevision++;check(CivilisationRuntime.Person(colony,9000)?.id==9000&&CivilisationRuntime.Person(colony,6)==null,"Identity index handles replacement without list growth");
            var random=(Func<long,string,double>)Delegate.CreateDelegate(typeof(Func<long,string,double>),typeof(CivilisationRuntime).GetMethod("Random",BindingFlags.Static|BindingFlags.NonPublic));foreach(long id in new[]{0L,1L,123456789L,long.MaxValue,long.MinValue})check(random(id,"fixture")==PlanetResourceProfile.Random(id+":fixture"),"Allocation-free random preserves the previous seed for "+id);
            random(1,"fixture");check(Allocation(()=>{for(int i=0;i<1000;i++)random(i,"fixture");})==0,"Warm society random sampling has no measured managed heap growth");
            report.roadCount=41726;report.oldRoadGeometryBytes=41726L*(81*76+384*4);report.sparseRoadGpuBytes=(long)cells.Length*16+6*64*64;
            var args=Environment.GetCommandLineArgs();int at=Array.IndexOf(args,"-planet-output");string output=at<0?"TestResults/RoadTerrain/After":args[at+1];Directory.CreateDirectory(output);File.WriteAllText(Path.Combine(output,"road-surface.json"),JsonUtility.ToJson(report,true));UnityEngine.Object.Destroy(go);UnityEngine.Object.Destroy(planet);
        }
        static void Measure(Report report,string name,Action operation,int iterations){operation();var timings=new double[iterations];double total=0;long bytes=Allocation(()=>{for(int i=0;i<iterations;i++){long start=Stopwatch.GetTimestamp();operation();double ms=(Stopwatch.GetTimestamp()-start)*1000d/Stopwatch.Frequency;timings[i]=ms;total+=ms;}});Array.Sort(timings);GetProcessMemoryInfo(GetCurrentProcess(),out var memory,(uint)System.Runtime.InteropServices.Marshal.SizeOf<Memory>());report.rows.Add(new Row{name=name,medianMs=timings[iterations/2],p95Ms=timings[(int)Math.Ceiling(iterations*.95)-1],updatesPerSecond=iterations*1000/total,managedHeapGrowthBytes=bytes/iterations,unityAllocated=Profiler.GetTotalAllocatedMemoryLong(),unityReserved=Profiler.GetTotalReservedMemoryLong(),workingSet=(long)memory.workingSet.ToUInt64()});}
    }
